import {groundCases,groundCase,groundCopy as copy,units} from './same-ground-content.mjs';
import {createGroundPlot,groundModel,setGroundWidth,layGroundRow,liftGroundRow,returnGroundTiles,walkGroundEdge,restartGroundWalk,revealGroundEdges,keepGroundPicture,clearGroundPicture,groundComparison,groundShortcut} from './same-ground-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null;
export function resetSameGround(){visit=null;}
function current(notebook,owner){if(!visit||visit.notebook!==notebook||visit.owner!==owner)visit={notebook,owner,caseId:'four',plots:new Map(),shared:false,shortcut:false,status:''};if(!visit.plots.has(visit.caseId))visit.plots.set(visit.caseId,createGroundPlot(visit.caseId));return visit;}
const button=(action,label,disabled=false)=>`<button type="button" data-ground-action="${action}"${disabled?' disabled':''}>${esc(label)}</button>`;
function art(m,picture=false,viewHeight=216){
 const id=picture?'picture':'plot',w=m.width,h=m.rows;
 const cells=Array.from({length:w*h},(_,i)=>`<rect data-ground-unit x="${12+i%w*16}" y="${12+Math.floor(i/w)*16}" width="16" height="16" fill="url(#ground-hatch-${id})" stroke="#52675e" stroke-width=".8"/>`).join('');
 const edges=picture?[]:m.edges.map((e,i)=>`<path d="M${12+e[0]*16} ${12+e[1]*16}L${12+e[2]*16} ${12+e[3]*16}" class="ground-edge${i<m.walked?' walked':m.reveal?' revealed':''}"/>`).join('');
 const point=!picture&&m.walked?m.edges[m.walked-1].slice(2):[0,0];
 return `<svg class="ground-svg" data-ground-diagram="${id}" viewBox="0 0 216 ${viewHeight}" style="aspect-ratio:216/${viewHeight}" role="img" aria-labelledby="ground-art-${id}"><title id="ground-art-${id}">${picture?'Kept picture':'Current plot'}: ${w} squares in each row, ${h} rows; ${units(w*h,'square unit')}, ${units(h?2*(w+h):0,'length unit')} around.</title><defs><pattern id="ground-hatch-${id}" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="#fff"/><path d="M0 6L6 0" stroke="#a9c9b7" stroke-width="1"/></pattern></defs><rect x="4" y="4" width="208" height="${viewHeight-8}" rx="8" fill="#eaf4ef"/>${cells}${h?`<rect x="12" y="12" width="${w*16}" height="${h*16}" fill="none" stroke="#183f39" stroke-width="1.5"/>`:''}${edges}${h&&!picture?`<circle cx="${12+point[0]*16}" cy="${12+point[1]*16}" r="3.5" fill="#b18424" stroke="#183430" stroke-width="1"/>`:''}</svg>`;
}
function tray(n){return `<div class="ground-tray"><svg viewBox="0 0 152 30" aria-hidden="true">${Array.from({length:n},(_,i)=>`<rect x="${4+i%12*12}" y="${2+Math.floor(i/12)*13}" width="10" height="10" fill="#fff" stroke="#183f39"/>`).join('')}</svg><strong>${units(n,'tile')} left in the tray</strong></div>`;}
function shared(){return `<svg class="ground-shared" viewBox="0 0 120 66" role="img" aria-label="Two neighbouring unit squares: six outside edges; the shared line is inside."><rect x="15" y="15" width="80" height="40" fill="#eaf4ef" stroke="#16645b" stroke-width="3"/><path d="M55 15V55" stroke="#52675e" stroke-dasharray="4 3"/><path d="M15 10H55M55 10H95" stroke="#183430"/><text x="34" y="8" font-size="8">1</text><text x="74" y="8" font-size="8">1</text></svg>`;}
export function sameGroundPage(notebook,owner){
 const v=current(notebook,owner),p=v.plots.get(v.caseId),m=groundModel(p),c=groundCase(v.caseId),height=24+16*Math.max(1,m.rows,m.kept?.rows||0);
 return `<section class="panel ground-board" data-ground-root><div class="section-heading"><div><h1>${copy.title}</h1><p>${copy.job}</p></div><a class="pill" href="#workshop">Storm Workshop</a></div><label class="ground-case">Choose some tiles <select data-ground-case>${groundCases.map(x=>`<option value="${x.id}"${x.id===c.id?' selected':''}>${x.title}</option>`).join('')}</select></label><h2 id="ground-title" tabindex="-1" data-ground-read>${esc(c.prompt)}</h2><div class="ground-layout"><div class="ground-current"><div class="ground-worktop">${art(m,false,height)}<div class="ground-controls"><label>Squares in each row <select data-ground-width${m.rows?' disabled':''}>${Array.from({length:12},(_,i)=>`<option value="${i+1}"${i+1===m.width?' selected':''}>${i+1}</option>`).join('')}</select></label>${m.rows?`<p class="ground-lock">${copy.widthLock}</p>`:''}<div class="ground-buttons">${button('lay','Lay one row',!m.canLay)}${button('lift','Lift last row',!m.canLift)}${button('return','Return all tiles',!m.rows)}</div><div class="ground-counts" data-ground-read>${m.rows?`${units(m.width,'square')} in each row, ${units(m.rows,'row')}. Covers <strong>${units(m.area,'square unit')}</strong>. Outside edge: <strong>${units(m.perimeter,'length unit')}</strong>.`:`All ${units(m.stock,'tile')} are in the tray. Lay a row to begin.`}</div><div class="ground-buttons">${button('walk','Walk one edge',!m.canWalk)}${button('restart','Start walk again',!m.walked)}</div><p data-ground-read>Walked ${m.walked} of ${units(m.perimeter,'length unit')}.${m.perimeter&&m.walked===m.perimeter?' Back at the start.':''}</p>${button('reveal',m.reveal?'Hide outside edges':'Show outside edges',!m.rows)}</div></div>${tray(m.tray)}<p class="ground-unit" data-ground-read><span aria-hidden="true">□</span> ${copy.units}</p><div class="ground-buttons">${button('keep',m.kept?'Replace kept picture':'Keep this picture',!m.rows)}${m.kept?button('clear','Clear kept picture'):''}${hearButton('', 'Hear this plot')}</div><p class="ground-status" role="status" aria-live="polite">${esc(v.status)}</p></div>${m.kept?`<aside class="ground-picture"><h3>Kept picture</h3>${art({...m.kept,walked:0,reveal:false},true,height)}<p>${units(m.kept.width,'square')} in each row, ${units(m.kept.rows,'row')}. ${units(m.kept.area,'square unit')}; ${units(m.kept.perimeter,'length unit')} around.</p><p class="tiny">${copy.picture}</p></aside>`:''}</div><p class="ground-comparison" data-ground-read>${esc(groundComparison(p))}</p>${m.budget?`<p class="ground-budget" data-ground-read>${m.budget.allUsed?'All 24 tiles are in the plot':`There are ${units(m.tray,'tile')} left`}. ${units(m.perimeter,'length unit')} of fence is ${m.budget.within?'within':'over'} the 20-unit supply.${m.budget.allUsed?'':' Use the remaining tiles before calling this a whole-plot plan.'}</p>`:''}<div class="ground-help"><details data-ground-shared${v.shared?' open':''}><summary>Why don't we count the inside line?</summary>${shared()}<p>${copy.shared}</p></details><details data-ground-shortcut${v.shortcut?' open':''}><summary>A shortcut for counting</summary><p>${esc(groundShortcut(p))}</p></details></div><p class="ground-visit">${copy.visit}</p><details><summary>For grown-ups</summary><p>${copy.grownup}</p></details></section>`;
}
export function bindSameGround(notebook,ctx){
 const root=document.querySelector('[data-ground-root]');if(!root||!visit)return;
 const captured=visit,owner=visit.owner,id=visit.caseId,plot=visit.plots.get(id);
 const live=()=>root.isConnected&&document.querySelector('[data-ground-root]')===root&&location.hash==='#workshop/same-ground'&&visit===captured&&visit.caseId===id&&visit.plots.get(id)===plot&&(!ctx.isActive||ctx.isActive())&&ctx.notebook()===notebook&&ctx.explorerId()===owner;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};
 function redraw(selector){ctx.render();const target=document.querySelector(selector);ctx.focus(target&&!target.disabled?selector:'#ground-title');}
 function change(next,action){if(!next)return;stop();visit.plots.set(id,next);const m=groundModel(next);visit.status=action==='walk'?`Walked ${m.walked} of ${units(m.perimeter,'length unit')}.${m.walked===m.perimeter?' Back at the start.':''}`:`${units(m.area,'square unit')} covered; ${units(m.tray,'tile')} left in the tray.`;let focus=`[data-ground-action="${action}"]`;if(action==='lay'&&!m.canLay)focus='[data-ground-action="lift"]';if(action==='lift'&&!m.canLift)focus=m.canLay?'[data-ground-action="lay"]':'[data-ground-width]';if(action==='walk'&&!m.canWalk)focus='[data-ground-action="restart"]';if(action==='clear')focus='[data-ground-action="keep"]';redraw(focus);}
 root.querySelector('[data-ground-case]').addEventListener('change',e=>{if(!live()||!groundCase(e.target.value))return;stop();visit.caseId=e.target.value;visit.status='';if(!visit.plots.has(visit.caseId))visit.plots.set(visit.caseId,createGroundPlot(visit.caseId));redraw('[data-ground-case]');});
 root.querySelector('[data-ground-width]').addEventListener('change',e=>{if(!live()||e.target.disabled)return;const next=setGroundWidth(plot,Number(e.target.value));if(!next)return;stop();visit.plots.set(id,next);visit.status='';redraw('[data-ground-width]');});
 const actions={lay:layGroundRow,lift:liftGroundRow,return:returnGroundTiles,walk:walkGroundEdge,restart:restartGroundWalk,reveal:p=>revealGroundEdges(p,!p.reveal),keep:keepGroundPicture,clear:clearGroundPicture};
 root.querySelectorAll('[data-ground-action]').forEach(b=>b.addEventListener('click',()=>{if(!live()||b.disabled)return;const action=b.dataset.groundAction;change(actions[action]?.(plot),action);}));
 for(const [selector,key] of [['[data-ground-shared]','shared'],['[data-ground-shortcut]','shortcut']]){const detail=root.querySelector(selector);detail.querySelector('summary').addEventListener('click',()=>{if(live()){visit[key]=!detail.open;stop();}});detail.addEventListener('toggle',e=>{if(live()){visit[key]=e.target.open;stop();}});}
 root.addEventListener('click',e=>{const b=e.target.closest('[data-speak]');if(!b||!root.contains(b))return;if(!live()){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=[...root.querySelectorAll('[data-ground-read]')].map(x=>x.textContent.trim()).join(' ');},{capture:true});
}
